use xiom.io;
fn show_len[T](v: Vec[T]) {
  io.println(v.len().to_str());
}

fn main() -> Int {
  let ints: Vec[Int] = Vec[Int].new();
  ints.push(10); ints.push(20);
  let strs: Vec[Str] = Vec[Str].new();
  strs.push("hi"); strs.push("there"); strs.push("!");
  show_len(ints);
  show_len(strs);
  return 0;
}
